def gold_slugs(kind: str) -> list:
    """The gold page slugs of a kind: registers/gold.yaml when it exists (spec 06.12), else the M0 set."""
    p = REPO / "registers" / "gold.yaml"
    if p.exists():
        d = need_yaml().safe_load(p.read_text(encoding="utf-8")) or {}
        rows = d.get("gold", d) if isinstance(d, dict) else d
        if isinstance(rows, dict):
            v = rows.get(kind)
            if v:
                return [v] if isinstance(v, str) else list(v)
        elif isinstance(rows, list):
            hits = [r["slug"] for r in rows if isinstance(r, dict) and r.get("kind") == kind and r.get("slug")]
            if hits:
                return hits
    return GOLD_M0.get(kind, GOLD_M0["concept"])


def gold_paths(kind: str) -> list:
    """(slug, node directory or None) for each gold page of the kind. None means the page is not written yet."""
    out = []
    for s in gold_slugs(kind):
        hits = sorted((REPO / "nodes").glob(f"*/*/{s}/node.md"))
        out.append((s, str(hits[0].parent.relative_to(REPO)) if hits else None))
    return out


