def sections_for(kind: str) -> str:
    """The task text of the writer for a kind: the files, the sections in order and the rules of the kind."""
    secs, req, gen = SECTIONS.get(kind, SECTIONS["concept"])
    if not secs:
        return EXTRA[kind]
    lines = [f"1. `node.md`: the front matter, the lead (one paragraph with no heading, at most 80 words), and these `##` sections of the {kind} kind (spec 06.3), in this order:"]
    for s in secs:
        tags = []
        if s in req:
            tags.append("required")
        if s in gen:
            tags.append("generated")
        lines.append(f"   - {s}" + (f" ({', '.join(tags)})" if tags else ""))
    lines.append(f"   The main section, required for the page to be published, is {next(s for s in req if s != 'In plain words')}.")
    return "\n".join(lines) + "\n" + EXTRA.get(kind, "") + COMMON
